import java.sql.*;

public class UserLogin {
    public boolean authenticate(String username, String password) {
        // Validate input to prevent DoS and ensure reasonable length
        if (username == null || password == null || 
            username.length() > 50 || password.length() > 100) {
            return false;
        }

        // Use parameterized query with placeholders
        String query = "SELECT * FROM users WHERE username=? AND password=?";

        // Try-with-resources ensures automatic cleanup of connections
        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/webapp", "dbuser", "dbpass");
             PreparedStatement pstmt = conn.prepareStatement(query)) {

            // Safely bind parameters to prevent SQL injection
            pstmt.setString(1, username);
            pstmt.setString(2, password);

            try (ResultSet rs = pstmt.executeQuery()) {
                return rs.next();
            }
        } catch (SQLException e) {
            // Log securely without exposing sensitive details
            System.err.println("Authentication database error occurred");
            return false;
        }
    }
}
